      await sbFetch(cloudCfg, `agent_payable_rules?id=eq.${ruleId}`, { method: "DELETE", headers: { Prefer: "return=minimal" } });
      showToast(`Rule removed and ${entries.length} record(s) restored to their original amount.`);
